action.command:
$branch = git rev-parse --abbrev-ref HEAD 2>$null
if ($branch -notmatch '^feature/task-') { exit 0 }

$existing = gh pr list --head $branch --state open --json number 2>$null | ConvertFrom-Json
if ($existing.Count -gt 0) { exit 0 }

$taskNum = ($branch -replace '^feature/task-(\d+[\.\d]*).*', '$1')
$title = "feat(task-$taskNum): $(($branch -replace '^feature/task-\d+[\.\d]*-', '') -replace '-', ' ')"
if ($title.Length -gt 70) { $title = $title.Substring(0, 70) }

gh pr create --head $branch --base main --title $title --body "## Summary`n`nImplements task $taskNum as per .kiro/specs/task-manager-app/tasks.md`n`nCloses #$taskNum`n`n## What was implemented`n`nSee commit history for details.`n`n## What was tested`n`nSee test output in session log." 2>$null
